%[text] # Basic validation of Road Grade Profile block
%[text] Specify elevation profile, and derive road grade profile.
%[text] Use the derived road grade profile in the Road Grade Profile block, run simulation, and get the simulated elevation result.
%[text] Compare the specified elevation profile and the simulated one.
%[text] ## Setting
length_unit = "m";

elevation_profile = table( ...
  simscape.Value([0 50 100,  200 250 300,  400 450 500,  600 650 700,  800 850 900], length_unit)', ...
  simscape.Value([0 0 0, 1 1 1, 3 3 3, 6 6 6, 2 2 2], length_unit)', ...
  VariableNames = ["HorizontalDistance", "Elevation"] );

dx = 0.5;
%[text] ## Derivation / Preprocess
x_1 = value(elevation_profile.HorizontalDistance(1), length_unit);
x_end = value(elevation_profile.HorizontalDistance(end), length_unit);

% Horizontal distance for vertical profile
refined_x = x_1 : dx : x_end;

refined_elevation = interp1( ...
  value(elevation_profile.HorizontalDistance, length_unit), ...
  value(elevation_profile.Elevation, length_unit), refined_x, "makima");

dzdx_vec = gradient(refined_elevation, dx);

% Road grade profile (percent)
grade_pct = 100 * tan(dzdx_vec);
%[text] 
fig = figure; %[output:1dbdb129]
fig.Position(3:4) = [800, 400]; %[output:1dbdb129]
tl = tiledlayout(fig, 2, 1, TileSpacing="tight"); %[output:1dbdb129]

ax = nexttile(tl); %[output:1dbdb129]
plot(ax, refined_x, refined_elevation, LineWidth=2) %[output:1dbdb129]
hold(ax, "on");  axis(ax, "padded");  grid(ax, "on") %[output:1dbdb129]
sc = scatter(ax, value(elevation_profile.HorizontalDistance, length_unit), value(elevation_profile.Elevation, length_unit), 100); %[output:1dbdb129]
sc.Marker = "x";  sc.LineWidth = 2; %[output:1dbdb129]
title(ax, "Elevation") %[output:1dbdb129]
ylabel(ax, "(" + string(unit(elevation_profile.Elevation)) + ")") %[output:1dbdb129]

ax = nexttile(tl); %[output:1dbdb129]
plot(ax, refined_x, grade_pct, LineWidth=2) %[output:1dbdb129]
hold(ax, "on");  axis(ax, "padded");  grid(ax, "on") %[output:1dbdb129]
title(ax, "Road grade") %[output:1dbdb129]
ylabel(ax, "(%)") %[output:1dbdb129]
xlabel(ax, "Horizontal distance, x (" + length_unit + ")") %[output:1dbdb129]
%%
%[text] ## Simulation
model_name = "HarnessModel_RoadGradeProfile_CustomComponent";
load_system(model_name)
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime=bevutil1.CodeUtil.stringify(refined_x(end)));
setb = @setBlockParameter;
sim_in = setb(sim_in, model_name+"/Curvilinear Speed", "constant", "1");
sim_in = setb(sim_in, model_name+"/Curvilinear Speed", "constant_unit", length_unit+"/s");
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "x_vector", bevutil1.CodeUtil.stringify(refined_x));
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "x_vector_unit", length_unit);
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "grade_vector", bevutil1.CodeUtil.stringify(grade_pct));
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "profile_interp_method", "simscape.enum.interpolation.smooth");
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "initial_position", "0");
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "initial_position_unit", length_unit);
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "initial_elevation", "0");
sim_in = setb(sim_in, model_name+"/Road Grade Profile", "initial_elevation_unit", length_unit);
sim_out = sim(sim_in);
result = extractTimetable(sim_out.logsout);
%[text] 
% Road grade data table
RG_prep = timetable(seconds(refined_x'), grade_pct', VariableNames="f");
RG_sim = timetable(result.Time, result.("Grade percent"), VariableNames="f");
% Union of row times. Linearly resample.
SyncedRoadGrade = synchronize(RG_prep, RG_sim, "union", "linear");
SyncedRoadGrade.Properties.VariableNames = ["Prep", "Sim"];
road_grade_diff = SyncedRoadGrade.Sim - SyncedRoadGrade.Prep;
%[text] 
% Elevation data table
E_prep = timetable(seconds(refined_x'), refined_elevation', VariableNames="z");
E_sim = timetable(result.Time, result.("Elevation"), VariableNames="z");
% Union of row times. Linearly resample.
SyncedElevation = synchronize(E_prep, E_sim, "union", "linear");
SyncedElevation.Properties.VariableNames = ["Prep", "Sim"];
elevation_diff = SyncedElevation.Sim - SyncedElevation.Prep;
%%
%[text] ## Visualization
ax = axes(figure); %[output:9da36e63]
plot(ax, SyncedRoadGrade.Time, SyncedRoadGrade.Prep, LineWidth=4) %[output:9da36e63]
hold(ax, "on") %[output:9da36e63]
plot(ax, SyncedRoadGrade.Time, SyncedRoadGrade.Sim, LineWidth=1.5) %[output:9da36e63]
grid(ax, "on") %[output:9da36e63]
legend(ax, ["Prep", "Simulated"], Location="best") %[output:9da36e63]
xlabel(ax, "Time (s)") %[output:9da36e63]
ylabel(ax, "(%)") %[output:9da36e63]
title(ax, "Road grade") %[output:9da36e63]
ax = axes(figure); %[output:2f013ca6]
plot(ax, SyncedRoadGrade.Time, road_grade_diff, LineWidth=1.5) %[output:2f013ca6]
hold(ax, "on") %[output:2f013ca6]
grid(ax, "on") %[output:2f013ca6]
xlabel(ax, "Time (s)") %[output:2f013ca6]
ylabel(ax, "(%)") %[output:2f013ca6]
title(ax, "Road grade difference: Sim - Prep") %[output:2f013ca6]
ax = axes(figure); %[output:91653a78]
plot(ax, SyncedElevation.Time, SyncedElevation.Prep, LineWidth=4) %[output:91653a78]
hold(ax, "on") %[output:91653a78]
plot(ax, SyncedElevation.Time, SyncedElevation.Sim, LineWidth=1.5) %[output:91653a78]
grid(ax, "on") %[output:91653a78]
legend(ax, ["Prep", "Simulated"], Location="best") %[output:91653a78]
xlabel(ax, "Time (s)") %[output:91653a78]
ylabel(ax, "(" + length_unit + ")") %[output:91653a78]
title(ax, "Elevation") %[output:91653a78]
ax = axes(figure); %[output:103c4b16]
plot(ax, SyncedElevation.Time, elevation_diff, LineWidth=1.5) %[output:103c4b16]
hold(ax, "on") %[output:103c4b16]
grid(ax, "on") %[output:103c4b16]
xlabel(ax, "Time (s)") %[output:103c4b16]
ylabel(ax, "(" + length_unit + ")") %[output:103c4b16]
title(ax, "Elevation difference: Sim - Prep") %[output:103c4b16]
